-- V0009 contract v1.1 changes to the shipped v1a tables (row N-006). Contract 855b7e0 added three business code
-- lists (channel, sub_channel, geo_class) and 54 config keys of docs/24 s9.5 (programmes, content, field app
-- details, back office), and two risk signals whose weights extend cfg.geo.integrity_weight. V0005 and V0006 are
-- shipped and never edited, so the changes land here.

ALTER TABLE app.code_list DROP CONSTRAINT code_list_list_key_check;
ALTER TABLE app.code_list ADD CONSTRAINT code_list_list_key_check CHECK (list_key IN (
  'channel','sub_channel','geo_class','force_reason','edit_reason','void_reason','visit_outcome','skip_reason',
  'day_exception_reason','stock_variance_reason','task_type','leave_type','feedback_category','qc_fault_type',
  'payment_mode','outlet_close_reason','submit_void_reason'));

-- Config keys added or changed by contract v1.1 (docs/24 s9.5 at 855b7e0), generated like V0006. cfg.app.home_tiles and
-- cfg.web.menu_by_role default to {} until their seed matrices are written (docs/requests/db-config-matrices.md).

UPDATE app.cfg_key SET area = 'geo', kind = 'S', value_type = 'json', default_value = '{"GEO_MOCK": 100, "GEO_TELEPORT": 40, "GEO_ZERO_JITTER": 40, "GEO_PERFECT_ACCURACY": 20, "GEO_SAME_POINT": 30, "GEO_ROUTE_SINGLE_POINT": 40, "GEO_STALE_FIX": 20, "GEO_GNSS_INCONSISTENT": 30, "GEO_GNSS_TIME_SKEW": 30, "GEO_DEVICE_SERVER_MISMATCH": 40, "GEO_SHORT_VISIT_GAPS": 20, "DEVICE_NOT_OWNER": 60, "DEVICE_INTEGRITY_FAIL": 30, "DEVICE_DEBUG_ENABLED": 10, "DEVICE_MOCK_APP_PRESENT": 30, "DEVICE_POLICY_DRIFT": 10, "CLOCK_SKEW": 10, "GEO_OUT_OF_BOUNDS": 40, "CONFIG_STAMP_REGRESS": 20}'::jsonb, bounds = '{}'::jsonb, bounds_rule = 'each 0..300', scope_levels = ARRAY['global']::text[], risk_class = 2, risk_rule = NULL, effect = 'B', delivery = 'server', requires_ack = false, future_dated_only = false, editor_permission = 'cfg.edit.security', description_en = 'Geofence and location (docs/24 s9.5)', updated_at = now() WHERE key = 'cfg.geo.integrity_weight';
